import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  recoverInterruptedJobs,
  requeueJob,
  RETRY_DELAY_MS,
  setProgress,
  TRANSIENT_ERROR,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

/** Time for one processing step. */
const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db: DatabaseSync = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Runs one attempt of a claimed job. `row.attempts` already counts this attempt. */
async function runAttempt(row: JobRow): Promise<void> {
  const { id, attempts, fail_attempts: failAttempts, steps, input } = row;

  if (attempts <= failAttempts) {
    // Simulated transient failure: fails at its first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return requeueJob(db, id, 0);
    if (attempts >= MAX_ATTEMPTS) failJob(db, id, TRANSIENT_ERROR);
    else requeueJob(db, id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let completed = 1; completed <= steps; completed++) {
    await sleep(STEP_MS);
    if (stopping) return requeueJob(db, id, 0);
    setProgress(db, id, completed);
  }
  completeJob(db, id, input.toUpperCase());
}

const recovered = recoverInterruptedJobs(db);
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
writeHeartbeat(db);
const heartbeat = setInterval(() => writeHeartbeat(db), HEARTBEAT_MS);
console.log('worker started');

while (!stopping) {
  let row: JobRow | undefined;
  try {
    row = claimNextJob(db);
  } catch (e) {
    console.error('failed to claim a job:', e);
    await sleep(1_000);
    continue;
  }
  if (!row) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(row);
  } catch (e) {
    console.error(`attempt on job ${row.id} failed:`, e);
    try {
      requeueJob(db, row.id, Date.now() + 1_000);
    } catch {
      // The job stays `running`; it is requeued when the worker next starts.
    }
  }
}

clearInterval(heartbeat);
clearHeartbeat(db);
db.close();
console.log('worker stopped');

